/* 50 Startups MLR Explorer – every number comes from data.js (generated by compute_results.py) */
(() => {
  const D = window.STARTUP_DATA;
  if (!D) {
    document.querySelector("main").innerHTML =
      "<div class='card' style='margin-top:24px'>data.js not found – run <code>python compute_results.py</code> first.</div>";
    return;
  }

  // ---------- constants & helpers ----------
  const METHODS = [
    { id: "lasso", name: "Lasso (L1 Ranking)", short: "Lasso", icon: "fa-filter", tag: "Embedded", color: "#4f46e5" },
    { id: "forward", name: "Forward SFS", short: "Forward SFS", icon: "fa-arrow-trend-up", tag: "Greedy", color: "#ff7f0e" },
    { id: "rfe", name: "RFE", short: "RFE", icon: "fa-scissors", tag: "Backward", color: "#2ca02c" },
    { id: "elasticnet", name: "ElasticNet", short: "ElasticNet", icon: "fa-diagram-project", tag: "L1 + L2", color: "#d62728" },
    { id: "exhaustive", name: "Exhaustive Search", short: "Exhaustive", icon: "fa-magnifying-glass-chart", tag: "Best Subset", color: "#9467bd" },
  ];
  const K = [1, 2, 3, 4, 5];
  const R = D.results;
  const $ = id => document.getElementById(id);
  const money = (v, d = 2) => (v < 0 ? "-$" : "$") + Math.abs(v).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
  const meta = id => METHODS.find(m => m.id === id);
  const bestK = m => R[m].reduce((b, r, i) => (r.rmse < R[m][b].rmse ? i : b), 0) + 1;
  const pText = p => (p < 1e-4 ? "< 0.0001" : p.toFixed(4));
  const ciFmt = v => v.toLocaleString("en-US", Math.abs(v) < 10 ? { minimumFractionDigits: 4, maximumFractionDigits: 4 } : { maximumFractionDigits: 2 });

  const state = { method: "lasso", k: 2, compare: false };

  // global best across all methods / ks
  let G = { m: null, k: 0, rmse: Infinity };
  METHODS.forEach(({ id }) => R[id].forEach((r, i) => { if (r.rmse < G.rmse) G = { m: id, k: i + 1, rmse: r.rmse }; }));
  const FULL = R.lasso[4];
  // most common best-k across methods (the "consensus" sweet spot)
  const kVotes = {};
  METHODS.forEach(({ id }) => { const b = bestK(id); kVotes[b] = (kVotes[b] || 0) + 1; });
  const consensusK = +Object.entries(kVotes).sort((a, b) => b[1] - a[1])[0][0];
  const consensusRMSE = R.lasso[consensusK - 1].rmse;

  // ---------- hero ----------
  $("hero-text").innerHTML = `Compare 5 Machine Learning Feature Selection Algorithms (<strong>Lasso</strong>, <strong>Forward SFS</strong>,
    <strong>RFE</strong>, <strong>ElasticNet</strong>, <strong>Exhaustive Search</strong>) against Baseline OLS.
    Explore the bias-variance tradeoff across feature counts <em>k</em> = 1 … 5, pinpointing the
    <strong>${consensusK}-feature optimal sweet spot</strong> and the <strong>5-feature overfitting cliff</strong>.`;
  $("hero-tags").innerHTML = `
    <span class="hero-pill"><i class="fa-solid fa-database"></i> 50 Startups Dataset</span>
    <span class="hero-pill"><i class="fa-solid fa-bolt"></i> 5 Selection Methods</span>
    <span class="hero-pill"><i class="fa-solid fa-star" style="color:#34d399"></i> Sweet Spot: k=${consensusK} (${money(consensusRMSE)} RMSE, ${kVotes[consensusK]}/5 methods)</span>
    ${G.k !== consensusK || G.rmse < consensusRMSE - 1e-6 ? `<span class="hero-pill"><i class="fa-solid fa-trophy" style="color:#fcd34d"></i> Global Min: ${meta(G.m).short} k=${G.k} (${money(G.rmse)})</span>` : ""}
    <span class="hero-pill"><i class="fa-solid fa-triangle-exclamation" style="color:#fbbf24"></i> Overfitting Warning: k=5 (${money(FULL.rmse)} RMSE)</span>`;

  // ---------- controls ----------
  function renderControls() {
    $("algoTabs").innerHTML = METHODS.map(m => `
      <button class="tab-btn ${!state.compare && state.method === m.id ? "active" : ""}" data-m="${m.id}" id="tab-${m.id}">
        <i class="fa-solid ${m.icon}"></i> ${m.name} <span class="badge-pill">${m.tag}</span>
      </button>`).join("") + `
      <button class="tab-btn compare ${state.compare ? "active" : ""}" id="tab-compare">
        <i class="fa-solid fa-layer-group"></i> 🌟 Compare All 5 Methods
      </button>`;
    const bk = bestK(state.method);
    $("kSelectorGroup").innerHTML = K.map(k => {
      const feats = R[state.method][k - 1].features;
      let cls = "", label;
      if (k === bk) { cls = "sweet-spot"; label = `k = ${k} ★ Optimal Sweet Spot <small>(Min RMSE)</small>`; }
      else if (k === 5) { cls = "overfitting"; label = `k = 5 ⚠ Full Model <small>(Overfitting Cliff)</small>`; }
      else { const add = k === 1 ? feats[0] : "+ " + feats[k - 1].replace("State_", "State: "); label = `k = ${k} <small>(${add})</small>`; }
      return `<button class="k-btn ${cls} ${state.k === k ? "active" : ""}" data-k="${k}" id="k-btn-${k}">${label}</button>`;
    }).join("");

    document.querySelectorAll("#algoTabs [data-m]").forEach(b => b.onclick = () => {
      state.method = b.dataset.m; state.compare = false; update();
    });
    $("tab-compare").onclick = () => { state.compare = !state.compare; update(); };
    document.querySelectorAll("#kSelectorGroup [data-k]").forEach(b => b.onclick = () => { state.k = +b.dataset.k; update(); });
  }

  const current = () => R[state.method][state.k - 1];

  // ---------- metrics ----------
  function renderMetrics() {
    const r = current();
    const bk = bestK(state.method);
    const isBest = state.k === bk, isCliff = state.k === 5;
    const isGlobal = Math.abs(r.rmse - G.rmse) < 1e-6;
    const rmseBadge = isBest
      ? `<span class="badge-tag badge-green"><i class="fa-solid fa-award"></i> Optimal Sweet Spot</span>`
      : isCliff ? `<span class="badge-tag badge-amber"><i class="fa-solid fa-triangle-exclamation"></i> Overfitting Cliff</span>`
      : `<span class="badge-tag badge-blue">k = ${state.k}</span>`;
    const cardCls = isBest ? "sweet" : isCliff ? "alert" : "";
    $("metricsGrid").innerHTML = `
      <div class="metric-card ${cardCls}">
        <div class="metric-title"><span>Test RMSE</span>${rmseBadge}</div>
        <div class="metric-val pop">${money(r.rmse)}</div>
        <div class="metric-note">Lower is better${isGlobal ? " (Best across methods)" : ""}</div>
      </div>
      <div class="metric-card ${cardCls}">
        <div class="metric-title"><span>R² Score</span><span class="badge-tag badge-blue"><i class="fa-solid fa-circle-check"></i> ${(r.r2 * 100).toFixed(1)}% Fit</span></div>
        <div class="metric-val pop">${r.r2.toFixed(4)}</div>
        <div class="metric-note">Explains ${(r.r2 * 100).toFixed(2)}% of profit variance</div>
      </div>
      <div class="metric-card">
        <div class="metric-title"><span>Adjusted R²</span><i class="fa-solid fa-scale-balanced" style="color:var(--slate-400)"></i></div>
        <div class="metric-val pop">${r.adj_r2.toFixed(4)}</div>
        <div class="metric-note">Penalizes redundant parameters</div>
      </div>
      <div class="metric-card">
        <div class="metric-title"><span>Mean Absolute Error</span><i class="fa-solid fa-calculator" style="color:var(--slate-400)"></i></div>
        <div class="metric-val pop">${money(r.mae)}</div>
        <div class="metric-note">Average prediction error ($)</div>
      </div>
      <div class="metric-card">
        <div class="metric-title"><span>F-Statistic</span><span class="badge-tag ${r.f_p < 0.05 ? "badge-green" : "badge-amber"}">p ${r.f_p < 1e-4 ? "&lt; 0.0001" : "= " + r.f_p.toFixed(4)}</span></div>
        <div class="metric-val pop">${r.f_stat.toFixed(1)}</div>
        <div class="metric-note">${r.f_p < 0.05 ? "Model is highly statistically significant" : "Not significant at α = 0.05"}</div>
      </div>`;

    $("featuresCount").textContent = r.features.length;
    $("featuresListChips").innerHTML = r.features.map(f => `<span class="feature-chip">${f}</span>`).join("");

    const n = $("parsimonyNotice");
    if (isBest) {
      n.className = "badge-tag badge-green notice";
      n.innerHTML = `<i class="fa-solid fa-star"></i> Occam's Razor: ${state.k} feature${state.k > 1 ? "s" : ""} yield the minimum test RMSE (${money(r.rmse)}) for ${meta(state.method).short}.`;
    } else if (isCliff) {
      n.className = "badge-tag badge-amber notice";
      n.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> Overfitting Warning: adding Administration &amp; State dummies raises error to ${money(r.rmse)}!`;
    } else {
      const b = R[state.method][bk - 1];
      n.className = "badge-tag badge-blue notice";
      n.innerHTML = `<i class="fa-solid fa-circle-info"></i> ${state.k} predictors: ${money(r.rmse - b.rmse)} worse than the k=${bk} sweet spot.`;
    }
  }

  // ---------- charts ----------
  const charts = {};
  Chart.defaults.font.family = "Inter";
  Chart.defaults.color = "#64748b";
  const tooltip = {
    backgroundColor: "rgba(15, 23, 42, 0.92)", titleFont: { family: "Outfit", size: 13 },
    bodyFont: { family: "Inter", size: 12 }, padding: 12, cornerRadius: 8,
  };
  function mk(id, cfg) { charts[id]?.destroy(); charts[id] = new Chart($(id), cfg); }

  function lineChart(id, key, yTitle) {
    const list = state.compare ? METHODS : [meta(state.method)];
    mk(id, {
      type: "line",
      data: {
        labels: K.map(String),
        datasets: list.map(m => {
          const bk = bestK(m.id);
          return {
            label: m.short, data: R[m.id].map(r => r[key]),
            borderColor: m.color, backgroundColor: m.color, borderWidth: state.compare ? 2 : 2.5, tension: 0.1,
            pointRadius: K.map(k => (!state.compare && k === state.k ? 8 : k === bk ? 6 : 4)),
            pointBackgroundColor: K.map(k => (k === bk ? "#10b981" : k === 5 ? "#f59e0b" : m.color)),
            pointBorderColor: "#fff", pointBorderWidth: 2,
          };
        }),
      },
      options: {
        responsive: true, maintainAspectRatio: false, animation: { duration: 450 },
        interaction: { mode: "nearest", intersect: false },
        plugins: {
          legend: { display: state.compare, position: "top", labels: { boxWidth: 10, usePointStyle: true } },
          tooltip: {
            ...tooltip,
            callbacks: {
              label: c => `${c.dataset.label}: ${key === "rmse" ? money(c.parsed.y) : c.parsed.y.toFixed(4)}`,
              afterLabel: c => {
                const m = METHODS.find(x => x.short === c.dataset.label);
                return "Features: " + R[m.id][c.dataIndex].features.join(", ");
              },
            },
          },
        },
        scales: {
          x: { title: { display: true, text: "Number of Features (k)", font: { weight: 600 } }, grid: { color: "#f1f5f9" } },
          y: { title: { display: true, text: yTitle, font: { weight: 600 } }, grid: { color: "#f1f5f9" } },
        },
        onClick: (e, els) => { if (els.length) { state.k = els[0].index + 1; if (state.compare) state.method = METHODS[els[0].datasetIndex].id; state.compare = false; update(); } },
      },
    });
  }

  function renderCharts() {
    lineChart("rmseChart", "rmse", "RMSE ($) (Lower is Better)");
    lineChart("r2Chart", "r2", "R-squared (Higher is Better)");

    const m = R[state.method], bk = bestK(state.method);
    $("rmseChartBadge").textContent = state.compare ? "Comparing 5 Methods" : meta(state.method).short;
    $("r2ChartBadge").textContent = state.compare ? "Comparing 5 Methods" : `Peak at k=${bk}`;
    $("rmseSubtitle").textContent = state.compare
      ? "Lower is better. Click a point to load that model."
      : `Lower is better. Valley at k=${bk} (${money(m[bk - 1].rmse)}), jump at k=5 (${money(m[4].rmse)}).`;
    $("r2Subtitle").textContent = state.compare
      ? "Higher is better. All methods converge at k=5."
      : `Higher is better. Peaks at k=${bk} (${m[bk - 1].r2.toFixed(4)}), drops at k=5 (${m[4].r2.toFixed(4)}).`;

    // coefficient bar chart
    const r = current();
    const cs = r.coef_stats.filter(c => c.feature !== "(Intercept)");
    mk("coefChart", {
      type: "bar",
      data: {
        labels: cs.map(c => c.feature.replace("State_", "State: ").replace(" Spend", "")),
        datasets: [{
          data: cs.map(c => c.coef), borderRadius: 6,
          backgroundColor: cs.map(c => c.feature.startsWith("State_") ? "#f59e0b" : c.coef >= 0 ? "#4f46e5" : "#ef4444"),
        }],
      },
      options: {
        indexAxis: "y", responsive: true, maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: { ...tooltip, callbacks: { label: c => c.label.startsWith("State") ? `${money(c.parsed.x)} vs California` : `${c.parsed.x >= 0 ? "+" : ""}$${c.parsed.x.toFixed(4)} profit per $1` } },
        },
        scales: { x: { grid: { color: "#f1f5f9" } }, y: { grid: { display: false } } },
      },
    });

    // actual vs predicted scatter
    const lo = Math.floor(Math.min(...r.actual, ...r.pred) * 0.9 / 20000) * 20000;
    const hi = Math.ceil(Math.max(...r.actual, ...r.pred) * 1.05 / 20000) * 20000;
    $("scatterBadge").textContent = `${meta(state.method).short} · k = ${state.k}`;
    mk("scatterChart", {
      type: "scatter",
      data: {
        datasets: [
          { label: "Test startups", data: r.actual.map((a, i) => ({ x: a, y: r.pred[i] })), backgroundColor: "rgba(79,70,229,0.85)", borderColor: "#fff", borderWidth: 2, pointRadius: 7, pointHoverRadius: 10 },
          { label: "Perfect fit (y = x)", type: "line", data: [{ x: lo, y: lo }, { x: hi, y: hi }], borderColor: "#ef4444", borderDash: [6, 6], pointRadius: 0, borderWidth: 2 },
        ],
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { position: "top", labels: { boxWidth: 10, usePointStyle: true } }, tooltip: { ...tooltip, callbacks: { label: c => `Actual ${money(c.parsed.x, 0)} → Predicted ${money(c.parsed.y, 0)}` } } },
        scales: {
          x: { min: lo, max: hi, title: { display: true, text: "Actual Profit ($)", font: { weight: 600 } }, grid: { color: "#f1f5f9" } },
          y: { min: lo, max: hi, title: { display: true, text: "Predicted Profit ($)", font: { weight: 600 } }, grid: { color: "#f1f5f9" } },
        },
      },
    });

    // residual bars (in test order sorted by actual)
    const ord = [...r.outliers].sort((a, b) => a.actual - b.actual);
    mk("residChart", {
      type: "bar",
      data: {
        labels: ord.map(o => `#${o.index}`),
        datasets: [{ data: ord.map(o => o.residual), borderRadius: 6, backgroundColor: ord.map(o => (o.abs_error > 10000 ? "#f59e0b" : o.residual >= 0 ? "#10b981" : "#6366f1")) }],
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false }, tooltip: { ...tooltip, callbacks: { title: c => `Startup ${c[0].label}`, label: c => `Residual ${money(c.parsed.y)}` } } },
        scales: {
          x: { title: { display: true, text: "Test startup (sorted by actual profit)", font: { weight: 600 } }, grid: { display: false } },
          y: { title: { display: true, text: "Residual ($)", font: { weight: 600 } }, grid: { color: "#f1f5f9" } },
        },
      },
    });
  }

  // ---------- equation & coefficient table ----------
  function renderEquation() {
    const cs = current().coef_stats;
    const parts = [`<span class="eq-intercept">${cs[0].coef.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>`];
    cs.slice(1).forEach(c => parts.push(`${c.coef >= 0 ? '<span class="eq-pos">+</span>' : '<span class="eq-neg">−</span>'} ${Math.abs(c.coef).toFixed(4)} × <span class="eq-var">(${c.feature})</span>`));
    $("equationBox").innerHTML = `<strong>Profit</strong> = ${parts.join(" ")}`;

    $("coefTableBody").innerHTML = cs.map(c => {
      const p = c.pvalue < 0.05
        ? `<span class="badge-tag badge-green">${pText(c.pvalue)} <i class="fa-solid fa-check"></i></span>`
        : `<span class="badge-tag badge-amber">${c.pvalue.toFixed(4)} (n.s.)</span>`;
      const v = c.vif == null ? "–" : c.vif < 5
        ? `<span class="badge-tag badge-green">${c.vif.toFixed(2)} (Safe)</span>`
        : `<span class="badge-tag badge-amber">${c.vif.toFixed(2)} (Collinear)</span>`;
      return `<tr>
        <td><strong>${c.feature}</strong></td>
        <td class="mono" style="font-weight:600">${c.coef.toLocaleString("en-US", { minimumFractionDigits: 4, maximumFractionDigits: 4 })}</td>
        <td>${c.stderr.toLocaleString("en-US", { maximumFractionDigits: 4 })}</td>
        <td>${c.tstat.toFixed(3)}</td>
        <td>${p}</td>
        <td style="font-size:12px;color:var(--slate-600)">[${ciFmt(c.ci_lower)}, ${ciFmt(c.ci_upper)}]</td>
        <td>${v}</td>
      </tr>`;
    }).join("");
  }

  // ---------- outliers ----------
  function renderOutliers() {
    $("outliersTableBody").innerHTML = current().outliers.map(o => {
      const high = o.abs_error > 10000;
      return `<tr>
        <td style="font-weight:700">#${o.rank}</td>
        <td>Startup #${o.index}</td>
        <td class="mono">${money(o.actual)}</td>
        <td class="mono">${money(o.predicted)}</td>
        <td style="color:${o.residual >= 0 ? "#059669" : "#dc2626"};font-weight:600">${o.residual >= 0 ? "+" : ""}${money(o.residual)}</td>
        <td>${money(o.abs_error)}</td>
        <td>${o.pct_error.toFixed(2)}%</td>
        <td>${high
          ? '<span class="badge-tag badge-amber"><span class="status-dot dot-amber"></span> High Residual</span>'
          : '<span class="badge-tag badge-green"><span class="status-dot dot-green"></span> In Range</span>'}</td>
      </tr>`;
    }).join("");
  }

  // ---------- comparison matrix ----------
  function renderMatrix() {
    $("matrixTable").innerHTML = `<thead><tr><th>Method</th>${K.map(k => `<th>k = ${k}</th>`).join("")}<th>Best k</th></tr></thead><tbody>` +
      METHODS.map(m => {
        const bk = bestK(m.id);
        return `<tr><td><i class="fa-solid ${m.icon}" style="color:${m.color}"></i> <strong>${m.name}</strong></td>` +
          K.map(k => {
            const r = R[m.id][k - 1];
            const sel = !state.compare && m.id === state.method && k === state.k;
            return `<td class="cell ${k === bk ? "best" : ""} ${k === 5 ? "cliff" : ""} ${sel ? "sel" : ""}" data-m="${m.id}" data-k="${k}" title="${r.features.join(", ")}">${money(r.rmse)}${k === bk ? " ★" : ""}</td>`;
          }).join("") + `<td><span class="badge-tag badge-green">k = ${bk}</span></td></tr>`;
      }).join("") + "</tbody>";
    document.querySelectorAll("#matrixTable td.cell").forEach(td => td.onclick = () => {
      state.method = td.dataset.m; state.k = +td.dataset.k; state.compare = false; update();
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

  // ---------- live predictor ----------
  const desc = D.eda.describe;
  const INPUTS = [
    { f: "R&D Spend", id: "RD", val: 100000 },
    { f: "Marketing Spend", id: "Mkt", val: 150000 },
    { f: "Administration", id: "Admin", val: 120000 },
  ];
  $("calcInputs").innerHTML = INPUTS.map(({ f, id, val }) => {
    const max = Math.ceil((desc[f].max * 1.1) / 5000) * 5000;
    return `<div class="input-group" id="group${id}">
      <div class="input-label-row"><span>${f} ($)</span><span class="usage-tag" id="use${id}"></span><span class="val" id="label${id}">${money(val, 0)}</span></div>
      <input type="number" id="num${id}" class="input-field" value="${val}" min="0" max="${max}" step="1000" aria-label="${f}">
      <input type="range" id="range${id}" class="range-slider" value="${val}" min="0" max="${max}" step="1000" aria-label="${f} slider">
    </div>`;
  }).join("");
  INPUTS.forEach(({ id }) => {
    const num = $("num" + id), rng = $("range" + id), lab = $("label" + id);
    rng.oninput = () => { num.value = rng.value; lab.textContent = money(+rng.value, 0); predict(); };
    num.oninput = () => { rng.value = num.value; lab.textContent = money(+num.value || 0, 0); predict(); };
  });
  $("selectState").onchange = predict;

  function predict() {
    const r = current();
    const st = $("selectState").value;
    const x = {
      "R&D Spend": +$("numRD").value || 0,
      "Marketing Spend": +$("numMkt").value || 0,
      Administration: +$("numAdmin").value || 0,
      State_Florida: st === "Florida" ? 1 : 0,
      "State_New York": st === "New York" ? 1 : 0,
    };
    let y = r.intercept;
    const parts = [];
    Object.entries(r.coef).forEach(([f, c]) => {
      const contrib = c * x[f];
      y += contrib;
      if (x[f] !== 0 || !f.startsWith("State_")) parts.push(`${f.replace("State_", "")}: ${contrib >= 0 ? "+" : ""}${money(contrib, 0)}`);
    });
    $("predProfitOutput").textContent = money(y);
    $("predFormulaNote").innerHTML = `Active predictors: ${r.features.join(", ")}<br><span class="parts">(β₀ ${money(r.intercept, 0)} | ${parts.join(" | ")})</span>`;

    // grey-out unused inputs
    INPUTS.forEach(({ f, id }) => {
      const used = r.features.includes(f);
      $("group" + id).classList.toggle("off", !used);
      $("use" + id).textContent = used ? "in model" : "ignored";
      $("use" + id).classList.toggle("on", used);
    });
    const stUsed = r.features.some(f => f.startsWith("State_"));
    $("inputGroupState").classList.toggle("off", !stUsed);
    $("useState").textContent = stUsed ? "in model" : "ignored";
    $("useState").classList.toggle("on", stUsed);
  }

  // ---------- EDA ----------
  const corr = D.eda.corr.Profit;
  const ck = Object.keys(corr).filter(k => k !== "Profit");
  mk("corrChart", {
    type: "bar",
    data: { labels: ck, datasets: [{ data: ck.map(k => corr[k]), backgroundColor: ["#4f46e5", "#a5b4fc", "#818cf8"], borderRadius: 8 }] },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false }, tooltip: { ...tooltip, callbacks: { label: c => `r = ${c.parsed.y.toFixed(4)}` } } },
      scales: { y: { min: 0, max: 1, grid: { color: "#f1f5f9" } }, x: { grid: { display: false } } },
    },
  });
  const sp = D.eda.state_profit;
  mk("stateChart", {
    type: "bar",
    data: { labels: Object.keys(sp), datasets: [{ data: Object.values(sp), backgroundColor: ["#10b981", "#0ea5e9", "#ec4899"], borderRadius: 8 }] },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false }, tooltip: { ...tooltip, callbacks: { label: c => money(c.parsed.y) } } },
      scales: { y: { grid: { color: "#f1f5f9" } }, x: { grid: { display: false } } },
    },
  });
  $("stateSubtitle").textContent = "Startups per state: " + Object.entries(D.eda.state_counts).map(([s, n]) => `${s} ${n}`).join(" · ");
  $("baselineBadge").textContent = `Full model: R² ${FULL.r2.toFixed(4)} · RMSE ${money(FULL.rmse)}`;

  // ---------- dataset explorer ----------
  const rows = D.eda.rows;
  const cols = Object.keys(rows[0]);
  $("dataSubtitle").textContent = `${rows.length} rows · ${cols.length} columns · ${D.eda.missing} missing values · train ${D.eda.n_train} / test ${D.eda.n_test} (random_state = 0)`;
  const testIds = new Set(R.lasso[0].outliers.map(o => o.index));
  function renderData(q = "") {
    q = q.toLowerCase();
    const f = rows.map((r, i) => [r, i + 1]).filter(([r]) => !q || Object.values(r).some(v => String(v).toLowerCase().includes(q)));
    $("dataTable").innerHTML = `<thead><tr><th>#</th>${cols.map(c => `<th>${c}</th>`).join("")}<th>Split</th></tr></thead><tbody>` +
      f.map(([r, id]) => `<tr><td>${id}</td>${cols.map(c => `<td class="${typeof r[c] === "number" ? "mono" : ""}">${typeof r[c] === "number" ? r[c].toLocaleString("en-US") : r[c]}</td>`).join("")}
        <td>${testIds.has(id) ? '<span class="badge-tag badge-amber">Test</span>' : '<span class="badge-tag badge-blue">Train</span>'}</td></tr>`).join("") + "</tbody>";
  }
  $("dataSearch").oninput = e => renderData(e.target.value);
  renderData();

  // ---------- CRISP-DM ----------
  const crisp = [
    ["Business Understanding", ["Predict startup Profit from R&D, Administration, Marketing spend and State", "Stakeholders: analysts, executives, investors", "Success: high R², low MAE / RMSE"]],
    ["Data Understanding", [`50 rows × 5 columns, ${D.eda.missing} missing values`, `R&D ↔ Profit r = ${corr["R&D Spend"].toFixed(3)} (strongest)`, `Administration r = ${corr.Administration.toFixed(3)} (weak)`]],
    ["Data Preparation", ["One-hot encode State (drop_first → avoid dummy trap)", "California is the baseline category", "train_test_split 80 / 20, random_state = 0"]],
    ["Modeling", ["scikit-learn LinearRegression (OLS)", "Feature selection: Lasso, Forward SFS, RFE, ElasticNet, Exhaustive", "k = 1 … 5 predictors per method"]],
    ["Evaluation", [`Full model: R² ${FULL.r2.toFixed(4)}, RMSE ${money(FULL.rmse, 0)}`, `Sweet spot k=${consensusK}: RMSE ${money(consensusRMSE, 0)}`, "Fewer features generalize better (parsimony)"]],
    ["Deployment", ["Static website – deployable to GitHub Pages", "Model saved as startup_profit_model.joblib", "Monitor drift & retrain when R² drops"]],
  ];
  $("crispGrid").innerHTML = crisp.map(([t, items], i) =>
    `<div class="phase"><div class="num">${i + 1}</div><h4>${t}</h4><ul>${items.map(x => `<li>${x}</li>`).join("")}</ul></div>`).join("");

  // ---------- main update ----------
  function update() {
    renderControls();
    renderMetrics();
    renderCharts();
    renderEquation();
    renderOutliers();
    renderMatrix();
    predict();
  }
  update();
  // re-measure chart labels once the web fonts are loaded
  document.fonts?.ready.then(() => renderCharts());
})();
